  int last_jpeg_message;
  const char * const *addon_message_table;
  int first_addon_message;
  int last_addon_message;
};
extern struct jpeg_error_mgr *jpeg_std_error(struct jpeg_error_mgr *err);
extern void jpeg_CreateDecompress(void *cinfo, int version, size_t structsize);
extern void jpeg_destroy_decompress(void *cinfo);
static jmp_buf jb;
static void my_error_exit(void *cinfo) {
  struct jpeg_error_mgr *err = *(struct jpeg_error_mgr**)cinfo;
  char buf[200]; err->format_message(cinfo, buf);
  printf("ERR: %s\n", buf);
  longjmp(jb, 1);
}
