    Cb = [[0.0]*width for _ in range(height)]
    Cr = [[0.0]*width for _ in range(height)]
    for y in range(height):
        for x in range(width):
            p = pixels(x, y)
            if ncomp == 1:
                Y[y][x] = float(p)
            else:
