                Cb[y][x] = -0.168736*r - 0.331264*g + 0.5*b + 128
                Cr[y][x] = 0.5*r - 0.418688*g - 0.081312*b + 128
    def sample(plane, x, y):
        x = min(x, width-1); y = min(y, height-1)
        return plane[y][x]
    def subsample(plane, hs, vs):
        # returns function to sample downsampled plane at (x,y) in downsampled coords
        def f(x, y):
            s = 0.0
            for dy in range(vs):
                for dx in range(hs):
                    s += sample(plane, x*hs+dx, y*vs+dy)
            return s/(hs*vs)
        return f
