    def dht(cls, tid, bits, vals):
        return b'\xff\xc4' + struct.pack('>H', 2+1+16+len(vals)) + bytes([(cls<<4)|tid]) + bytes(bits) + bytes(vals)
    o += dht(0,0,DC_LUM_BITS,DC_LUM_VAL) + dht(1,0,AC_LUM_BITS,AC_LUM_VAL)
    if ncomp == 3:
        o += dht(0,1,DC_CHR_BITS,DC_CHR_VAL) + dht(1,1,AC_CHR_BITS,AC_CHR_VAL)
    if restart:
        o += b'\xff\xdd' + struct.pack('>HH', 4, restart)
    # SOS
    o += b'\xff\xda' + struct.pack('>HB', 6+2*ncomp, ncomp)
    if ncomp == 1: o += bytes([1, 0x00])
    else: o += bytes([1, 0x00, 2, 0x11, 3, 0x11])
    o += bytes([0, 63, 0])
    bw = BitWriter()
    mcuw = 8*hsamp; mcuh = 8*vsamp
    mcux = (width + mcuw - 1)//mcuw; mcuy = (height + mcuh - 1)//mcuh
    prev = [0,0,0]
    cbs = subsample(Cb, hsamp, vsamp); crs = subsample(Cr, hsamp, vsamp)
    mcu_count = 0; rst = 0
    for my in range(mcuy):
        for mx in range(mcux):
            if restart and mcu_count > 0 and mcu_count % restart == 0:
                bw.flush()
                bw.buf += bytes([0xFF, 0xD0 + (rst & 7)]); rst += 1
                prev = [0,0,0]
            for by in range(vsamp):
                for bx in range(hsamp):
                    blk = [sample(Y, mx*mcuw+bx*8+x, my*mcuh+by*8+y)-128 for y in range(8) for x in range(8)]
                    prev[0] = encode_block(bw, fdct(blk), ql, dcl, acl, prev[0])
            if ncomp == 3:
                blk = [cbs(mx*8+x, my*8+y)-128 for y in range(8) for x in range(8)]
                prev[1] = encode_block(bw, fdct(blk), qc, dcc, acc, prev[1])
                blk = [crs(mx*8+x, my*8+y)-128 for y in range(8) for x in range(8)]
                prev[2] = encode_block(bw, fdct(blk), qc, dcc, acc, prev[2])
            mcu_count += 1
    bw.flush()
    o += bw.buf
    o += b'\xff\xd9'
    if out:
        open(out, 'wb').write(o)
    return bytes(o)

if __name__ == '__main__':
    # quick demo: gradient
    w, h = int(sys.argv[1]), int(sys.argv[2])
    encode(w, h, lambda x, y: (x*255//max(1,w-1), y*255//max(1,h-1), 128), ncomp=3, quality=95, out=sys.argv[3])
