def build_huff(bits, vals):
    codes = {}
    code = 0; k = 0
    for l in range(1, 17):
        for _ in range(bits[l-1]):
            codes[vals[k]] = (code, l); k += 1; code += 1
        code <<= 1
    return codes

def scale_q(q, quality):
    quality = max(1, min(100, quality))
    s = 5000 // quality if quality < 50 else 200 - quality*2
    return [max(1, min(255, (v*s + 50)//100)) for v in q]

COS = [[math.cos((2*x+1)*u*math.pi/16) for x in range(8)] for u in range(8)]
def fdct(block):
    out = [0.0]*64
    for v in range(8):
        for u in range(8):
            s = 0.0
            for y in range(8):
                for x in range(8):
                    s += block[y*8+x]*COS[u][x]*COS[v][y]
            cu = 1/math.sqrt(2) if u == 0 else 1.0
            cv = 1/math.sqrt(2) if v == 0 else 1.0
            out[v*8+u] = 0.25*cu*cv*s
    return out

class BitWriter:
    def __init__(self): self.buf = bytearray(); self.acc = 0; self.n = 0
    def write(self, code, length):
        for i in range(length-1, -1, -1):
            self.acc = (self.acc << 1) | ((code >> i) & 1); self.n += 1
            if self.n == 8:
                self.buf.append(self.acc)
                if self.acc == 0xFF: self.buf.append(0)
                self.acc = 0; self.n = 0
    def flush(self):
        while self.n != 0: self.write(1, 1)

def encode_block(bw, coefs, q, dc_codes, ac_codes, prev_dc):
    qc = [int(round(coefs[i]/q[i])) for i in range(64)]
    zz = [qc[ZIGZAG[i]] for i in range(64)]
    diff = zz[0] - prev_dc
    def cat_bits(v):
        a = abs(v); n = 0
        while a: n += 1; a >>= 1
        bits = v if v >= 0 else (v + (1 << n) - 1)
        return n, bits
    n, bits = cat_bits(diff)
    c, l = dc_codes[n]; bw.write(c, l)
    if n: bw.write(bits, n)
    run = 0
    for i in range(1, 64):
        if zz[i] == 0:
            run += 1; continue
        while run > 15:
            c, l = ac_codes[0xF0]; bw.write(c, l); run -= 16
        n, bits = cat_bits(zz[i])
        c, l = ac_codes[(run << 4) | n]; bw.write(c, l); bw.write(bits, n)
        run = 0
    if run > 0:
        c, l = ac_codes[0x00]; bw.write(c, l)
    return zz[0]

def encode(width, height, pixels, ncomp=3, quality=90, hsamp=1, vsamp=1, out=None, restart=0, comment=None, extra_segments=None, no_jfif=False):
    """pixels: function (x,y)->(r,g,b) or gray int. ncomp 1 or 3. hsamp/vsamp: luma sampling factors (1 or 2)."""
    ql = scale_q(STD_LUM_Q, quality); qc = scale_q(STD_CHR_Q, quality)
    dcl = build_huff(DC_LUM_BITS, DC_LUM_VAL); acl = build_huff(AC_LUM_BITS, AC_LUM_VAL)
    dcc = build_huff(DC_CHR_BITS, DC_CHR_VAL); acc = build_huff(AC_CHR_BITS, AC_CHR_VAL)
    # build planes
    if ncomp == 1:
        hsamp = vsamp = 1
    Y = [[0.0]*width for _ in range(height)]
    Cb = [[0.0]*width for _ in range(height)]
    Cr = [[0.0]*width for _ in range(height)]
    for y in range(height):
        for x in range(width):
            p = pixels(x, y)
            if ncomp == 1:
                Y[y][x] = float(p)
            else:
                r, g, b = p
                Y[y][x] = 0.299*r + 0.587*g + 0.114*b
                Cb[y][x] = -0.168736*r - 0.331264*g + 0.5*b + 128
                Cr[y][x] = 0.5*r - 0.418688*g - 0.081312*b + 128
    def sample(plane, x, y):
        x = min(x, width-1); y = min(y, height-1)
        return plane[y][x]
    def subsample(plane, hs, vs):
        # returns function to sample downsampled plane at (x,y) in downsampled coords
        def f(x, y):
            s = 0.0
            for dy in range(vs):
                for dx in range(hs):
                    s += sample(plane, x*hs+dx, y*vs+dy)
            return s/(hs*vs)
        return f
    o = bytearray()
    o += b'\xff\xd8'
    if not no_jfif:
        o += b'\xff\xe0' + struct.pack('>H', 16) + b'JFIF\x00\x01\x01\x00' + struct.pack('>HH', 1, 1) + b'\x00\x00'
    if extra_segments:
        for seg in extra_segments: o += seg
    if comment is not None:
        o += b'\xff\xfe' + struct.pack('>H', len(comment)+2) + comment
    # DQT
    o += b'\xff\xdb' + struct.pack('>H', 2+65*(2 if ncomp==3 else 1))
    o += b'\x00' + bytes(ql[ZIGZAG[i]] for i in range(64))
    if ncomp == 3:
        o += b'\x01' + bytes(qc[ZIGZAG[i]] for i in range(64))
    # SOF0
    o += b'\xff\xc0' + struct.pack('>HBHHB', 8+3*ncomp, 8, height, width, ncomp)
    if ncomp == 1:
        o += bytes([1, 0x11, 0])
    else:
        o += bytes([1, (hsamp<<4)|vsamp, 0, 2, 0x11, 1, 3, 0x11, 1])
    # DHT
    def dht(cls, tid, bits, vals):
        return b'\xff\xc4' + struct.pack('>H', 2+1+16+len(vals)) + bytes([(cls<<4)|tid]) + bytes(bits) + bytes(vals)
    o += dht(0,0,DC_LUM_BITS,DC_LUM_VAL) + dht(1,0,AC_LUM_BITS,AC_LUM_VAL)
    if ncomp == 3:
        o += dht(0,1,DC_CHR_BITS,DC_CHR_VAL) + dht(1,1,AC_CHR_BITS,AC_CHR_VAL)
    if restart:
        o += b'\xff\xdd' + struct.pack('>HH', 4, restart)
    # SOS
    o += b'\xff\xda' + struct.pack('>HB', 6+2*ncomp, ncomp)
    if ncomp == 1: o += bytes([1, 0x00])
    else: o += bytes([1, 0x00, 2, 0x11, 3, 0x11])
    o += bytes([0, 63, 0])
    bw = BitWriter()
    mcuw = 8*hsamp; mcuh = 8*vsamp
    mcux = (width + mcuw - 1)//mcuw; mcuy = (height + mcuh - 1)//mcuh
    prev = [0,0,0]
    cbs = subsample(Cb, hsamp, vsamp); crs = subsample(Cr, hsamp, vsamp)
    mcu_count = 0; rst = 0
    for my in range(mcuy):
