                bw.flush()
                bw.buf += bytes([0xFF, 0xD0 + (rst & 7)]); rst += 1
                prev = [0,0,0]
            for by in range(vsamp):
                for bx in range(hsamp):
                    blk = [sample(Y, mx*mcuw+bx*8+x, my*mcuh+by*8+y)-128 for y in range(8) for x in range(8)]
