                prev[2] = encode_block(bw, fdct(blk), qc, dcc, acc, prev[2])
            mcu_count += 1
    bw.flush()
    o += bw.buf
    o += b'\xff\xd9'
    if out:
        open(out, 'wb').write(o)
    return bytes(o)

