            if (mode == 0) v += (RED*pr + GREEN*pg + BLUE*pb)/255.0f; else v += RED*pr + GREEN*pg + BLUE*pb;
            r += pr; g += pg; b += pb;
          }
        }
        if (mode == 0) { pix[lasty*w+x] += v / n; red[lasty*w+x] += r/n; green[lasty*w+x] += g/n; blue[lasty*w+x] += b/n; }
        else { pix[lasty*w+x] += v; red[lasty*w+x] += r; green[lasty*w+x] += g; blue[lasty*w+x] += b; }
      }
      yadds[lasty]++;
      lasty++;
    }
    lasty = y;
  }
  for (int y = 0; y < h; y++) {
    for (int x = 0; x < w; x++) {
      float v = pix[y*w+x], r = red[y*w+x], g = green[y*w+x], b = blue[y*w+x];
      int xl = lookup[x], xr = lookup[x+1]; int n = xr-xl+1;
      if (mode == 0) { v /= yadds[y]; r /= yadds[y]; g /= yadds[y]; b /= yadds[y]; r/=255.0f; g/=255.0f; b/=255.0f; }
      else { int cnt = yadds[y]*n; v /= cnt; r /= cnt; g /= cnt; b /= cnt; v /= 255.0f; r/=255.0f; g/=255.0f; b/=255.0f; }
      printf("%d,%d,%d ", ROUND(255.0f*r), ROUND(255.0f*g), ROUND(255.0f*b));
    }
