            else if (mode == 2) v += RED*(pr/255.0f) + GREEN*(pg/255.0f) + BLUE*(pb/255.0f);
            else if (mode == 3) v += (float)(RED*pr + GREEN*pg + BLUE*pb)/255.0f;
            else if (mode == 4) { float pr2 = pr/255.0f, pg2 = pg/255.0f, pb2 = pb/255.0f; v += RED*pr2 + GREEN*pg2 + BLUE*pb2; }
          }
        }
        pix[lasty*w+x] += v / n;
      }
      yadds[lasty]++;
      lasty++;
    }
    lasty = y;
  }
  for (int y = 0; y < h; y++) {
    for (int x = 0; x < w; x++) {
      float v = pix[y*w+x] / yadds[y];
      int idx = ROUND(v * (npal-1));
      putchar(pal[idx]);
    }
    printf("\n");
  }
