int main(int argc, char **argv) {
  struct jpeg_decompress_struct c; struct jpeg_error_mgr jerr;
  FILE *f = fopen(argv[1], "rb");
  c.err = jpeg_std_error(&jerr); jpeg_create_decompress(&c); jpeg_stdio_src(&c, f); jpeg_read_header(&c, 1); jpeg_start_decompress(&c);
  int W = c.output_width, H = c.output_height, nc = c.output_components;
