/*
 * jp2a-compatible JPEG to ASCII converter.
 *
 * Written from scratch based on observed behaviour of the reference
 * executable.  Uses libjpeg for decoding, libcurl for URL downloads and
 * ncurses/terminfo for terminal size detection.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <curl/curl.h>

#include "jpegapi.h"
#include "termsize.h"

#define VERSION_STRING "1.0.8"

#define ROUND(x) ((int)((x) + 0.5f))

/* ---------------------------------------------------------------------- */
/* Options                                                                 */
/* ---------------------------------------------------------------------- */

enum { TERM_FIT = 1, TERM_WIDTH, TERM_HEIGHT, TERM_ZOOM };

static int opt_width = 0;
static int opt_height = 0;
static int height_count = 0;      /* number of --height style settings   */
static int width_count = 1;       /* number of --width style settings    */
static int termfit = TERM_FIT;
static int fit_to_terminal = 0;   /* term-fit actually engaged (no dims) */

static int verbose = 0;
static int debug = 0;
static int invert = 0;
static int border = 0;
static int flipx = 0;
static int flipy = 0;
static int clearscr = 0;
static int usecolors = 0;
static int colorfill = 0;
static int grayscale = 0;
static int html = 0;
static int html_raw = 0;
static int html_bold = 1;
static int html_fontsize = 8;
static const char *html_title = "jp2a converted image";
static const char *output_filename = NULL;

static float red_weight = 0.2989f;
static float green_weight = 0.5866f;
static float blue_weight = 0.1145f;

static char ascii_palette[257] = "   ...',;:clodxkO0KXNWM";

static int term_cols = 80;
static int term_rows = 24;

static FILE *out = NULL;

/* ---------------------------------------------------------------------- */

static void print_version(FILE *f)
{
	fprintf(f,
		"jp2a %s\n"
		"Copyright 2006-2016 Christian Stigen Larsen\n"
		"Distributed under the GNU General Public License (GPL) v2.\n",
		VERSION_STRING);
}

static void print_help(void)
{
	print_version(stderr);
	fputs(
"\n"
"Usage: jp2a [ options ] [ file(s) | URL(s) ]\n"
"\n"
"Convert files or URLs from JPEG format to ASCII.\n"
"\n"
"OPTIONS\n"
"  -                 Read images from standard input.\n"
"      --blue=N.N    Set RGB to grayscale conversion weight, default is 0.1145\n"
"  -b, --border      Print a border around the output image.\n"
"      --chars=...   Select character palette used to paint the image.\n"
"                    Leftmost character corresponds to black pixel, right-\n"
"                    most to white.  Minimum two characters must be specified.\n"
"      --clear       Clears screen before drawing each output image.\n"
"      --colors      Use ANSI colors in output.\n"
"  -d, --debug       Print additional debug information.\n"
"      --fill        When used with --color and/or --html, color each character's\n"
"                    background color.\n"
"  -x, --flipx       Flip image in X direction.\n"
"  -y, --flipy       Flip image in Y direction.\n"
"  -f, --term-fit    Use the largest image dimension that fits in your terminal\n"
"                    display with correct aspect ratio.\n"
"      --term-height Use terminal display height.\n"
"      --term-width  Use terminal display width.\n"
"  -z, --term-zoom   Use terminal display dimension for output.\n"
"      --grayscale   Convert image to grayscale when using --html or --colors\n"
"      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866\n"
"      --height=N    Set output height, calculate width from aspect ratio.\n"
"  -h, --help        Print program help.\n"
"      --html        Produce strict XHTML 1.0 output.\n"
"      --html-fill   Same as --fill (will be phased out)\n"
"      --html-fontsize=N   Set fontsize to N pt, default is 4.\n"
"      --html-no-bold      Do not use bold characters with HTML output\n"
"      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.\n"
"      --html-title=...  Set HTML output title\n"
"  -i, --invert      Invert output image.  Use if your display has a dark\n"
"                    background.\n"
"      --background=dark   These are just mnemonics whether to use --invert\n"
"      --background=light  or not.  If your console has light characters on\n"
"                    a dark background, use --background=dark.\n"
"      --output=...  Write output to file.\n"
"      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.\n"
"      --size=WxH    Set output width and height.\n"
"  -v, --verbose     Verbose output.\n"
"  -V, --version     Print program version.\n"
"      --width=N     Set output width, calculate height from ratio.\n"
"\n"
"  The default mode is `jp2a --term-fit --background=dark'.\n"
"  See the man-page for jp2a for more detailed help text.\n"
"\n"
"Project homepage on https://github.com/cslarsen/jp2a\n"
"Report bugs to <csl@csl.name>\n", stderr);
}

static void unknown_option(const char *s)
{
	fprintf(stderr, "Unknown option %s\n\n", s);
	print_help();
	exit(1);
}

static int starts_with(const char *s, const char *prefix)
{
	return strncmp(s, prefix, strlen(prefix)) == 0;
}

/* Returns non-zero if the argument is an option (as opposed to a file). */
static int is_option(const char *s)
{
	return s[0] == '-' && s[1] != '\0';
}

static void parse_option(const char *s)
{
	if (!strcmp(s, "-h") || !strcmp(s, "--help")) {
		print_help();
		exit(0);
	}
	if (!strcmp(s, "-V") || !strcmp(s, "--version")) {
		print_version(stderr);
		exit(0);
	}
	if (!strcmp(s, "-v") || !strcmp(s, "--verbose")) { verbose = 1; return; }
	if (!strcmp(s, "-d") || !strcmp(s, "--debug")) { debug = 1; return; }
	if (!strcmp(s, "-b") || !strcmp(s, "--border")) { border = 1; return; }
	if (!strcmp(s, "-x") || !strcmp(s, "--flipx")) { flipx = 1; return; }
	if (!strcmp(s, "-y") || !strcmp(s, "--flipy")) { flipy = 1; return; }
	if (!strcmp(s, "-i") || !strcmp(s, "--invert")) { invert = !invert; return; }
	if (!strcmp(s, "--background=dark")) { invert = 0; return; }
	if (!strcmp(s, "--background=light")) { invert = 1; return; }
	if (!strcmp(s, "-f") || !strcmp(s, "--term-fit")) { termfit = TERM_FIT; return; }
	if (!strcmp(s, "-z") || !strcmp(s, "--term-zoom")) { termfit = TERM_ZOOM; return; }
	if (!strcmp(s, "--term-width")) { termfit = TERM_WIDTH; return; }
	if (!strcmp(s, "--term-height")) { termfit = TERM_HEIGHT; return; }
	if (!strcmp(s, "--clear")) { clearscr = 1; return; }
	if (!strcmp(s, "--colors") || !strcmp(s, "--color")) { usecolors = 1; return; }
	if (!strcmp(s, "--fill")) { colorfill = 1; return; }
	if (!strcmp(s, "--html-fill")) {
		fprintf(stderr, "warning: --html-fill has changed to --fill\n");
		colorfill = 1;
		return;
	}
	if (!strcmp(s, "--grayscale")) { grayscale = 1; usecolors = 1; return; }
	if (!strcmp(s, "--html")) { html = 1; return; }
	if (!strcmp(s, "--html-raw")) { html_raw = 1; return; }
	if (!strcmp(s, "--html-no-bold")) { html_bold = 0; return; }

	if (starts_with(s, "--html-fontsize=")) {
		if (sscanf(s, "--html-fontsize=%d", &html_fontsize) != 1)
			unknown_option(s);
		return;
	}
	if (starts_with(s, "--html-title=")) {
		html_title = s + strlen("--html-title=");
		return;
	}
	if (starts_with(s, "--output=")) {
		const char *name = s + strlen("--output=");
		if (*name == '\0') {
			fprintf(stderr, "Empty output filename.\n");
			exit(1);
		}
		output_filename = name;
		return;
	}
	if (starts_with(s, "--chars=")) {
		const char *pal = s + strlen("--chars=");
		strcpy(ascii_palette, pal);
		if (strlen(ascii_palette) < 2) {
			fprintf(stderr, "You must specify at least two characters in --chars.\n");
			exit(1);
		}
		return;
	}
	if (starts_with(s, "--red=")) {
		if (sscanf(s, "--red=%f", &red_weight) != 1) unknown_option(s);
		return;
	}
	if (starts_with(s, "--green=")) {
		if (sscanf(s, "--green=%f", &green_weight) != 1) unknown_option(s);
		return;
	}
	if (starts_with(s, "--blue=")) {
		if (sscanf(s, "--blue=%f", &blue_weight) != 1) unknown_option(s);
		return;
	}
	if (starts_with(s, "--size=")) {
		if (sscanf(s, "--size=%dx%d", &opt_width, &opt_height) != 2)
			unknown_option(s);
		width_count = 0;
		height_count = 0;
		return;
	}
	if (starts_with(s, "--width=")) {
		if (sscanf(s, "--width=%d", &opt_width) != 1) unknown_option(s);
		width_count++;
		return;
	}
	if (starts_with(s, "--height=")) {
		if (sscanf(s, "--height=%d", &opt_height) != 1) unknown_option(s);
		height_count++;
		return;
	}

	unknown_option(s);
}

/* ---------------------------------------------------------------------- */
/* Output dimension logic                                                  */
/* ---------------------------------------------------------------------- */

enum { ACT_NONE, ACT_CHECK, ACT_WIDTH_FROM_HEIGHT, ACT_HEIGHT_FROM_WIDTH };

/*
 * Decide how the output dimensions are derived from the user settings.
 * The behaviour depends on how many times width/height were given.
 */
static int dimension_action(void)
{
	int A = height_count;
	int B = width_count;

	if (B == 0)
		return A == 0 ? ACT_CHECK : ACT_WIDTH_FROM_HEIGHT;
	if (B == 1) {
		if (A == 0) return ACT_HEIGHT_FROM_WIDTH;
		if (A == 1) return ACT_WIDTH_FROM_HEIGHT;
		if (A == 2) return ACT_CHECK;
		return ACT_NONE;
	}
	return A == 0 ? ACT_HEIGHT_FROM_WIDTH : ACT_NONE;
}

static int calc_width(int h, int jw, int jh)
{
	return ROUND(2.0f * (float) h * (float) jw / (float) jh);
}

static int calc_height(int w, int jw, int jh)
{
	return ROUND(0.5f * (float) w * (float) jh / (float) jw);
}

static void apply_terminal_mode(void)
{
	int need_term = termfit == TERM_WIDTH || termfit == TERM_HEIGHT ||
		termfit == TERM_ZOOM ||
		(termfit == TERM_FIT && opt_width == 0 && opt_height == 0);

	if (!need_term)
		return;

	if (query_terminal_size(&term_cols, &term_rows) != 0)
		exit(1);

	switch (termfit) {
	case TERM_WIDTH:
		opt_width = term_cols;
		opt_height = 0;
		width_count++;
		break;
	case TERM_HEIGHT:
		opt_width = 0;
		opt_height = term_rows - 1;
		height_count++;
		break;
	case TERM_ZOOM:
		opt_width = term_cols;
		opt_height = term_rows - 1;
		width_count = 0;
		height_count = 0;
		break;
	case TERM_FIT:
		opt_height = term_rows - 1;
		height_count++;
		fit_to_terminal = 1;
		break;
	}
}

static void validate_dimensions(void)
{
	int bad = 0;
	switch (dimension_action()) {
	case ACT_CHECK:
		bad = opt_width <= 0 || opt_height <= 0;
		break;
	case ACT_WIDTH_FROM_HEIGHT:
		bad = opt_height <= 0;
		break;
	case ACT_HEIGHT_FROM_WIDTH:
		bad = opt_width <= 0;
		break;
	default:
		break;
	}
	if (bad) {
		fprintf(stderr, "Invalid width or height specified\n");
		exit(1);
	}
}

/* Compute the output size for an image of jw x jh pixels. */
static void compute_output_size(int jw, int jh, int *w_out, int *h_out)
{
	int w = opt_width, h = opt_height;

	switch (dimension_action()) {
	case ACT_WIDTH_FROM_HEIGHT:
		w = calc_width(h, jw, jh);
		while (w == 0) {
			++h;
			w = calc_width(h, jw, jh);
		}
		if (fit_to_terminal && w > term_cols) {
			w = term_cols;
			h = calc_height(w, jw, jh);
			while (h == 0) {
				++w;
				h = calc_height(w, jw, jh);
			}
		}
		break;
	case ACT_HEIGHT_FROM_WIDTH:
		h = calc_height(w, jw, jh);
		while (h == 0) {
			++w;
			h = calc_height(w, jw, jh);
		}
		break;
	default:
		break;
	}
	*w_out = w;
	*h_out = h;
}

/* ---------------------------------------------------------------------- */
/* Image accumulation                                                      */
/* ---------------------------------------------------------------------- */

typedef struct {
	int width, height;
	float *pixel;
	float *red, *green, *blue;
	int *yadds;
	int *lookup_x;
	float resize_y;
	int components;
} Image;

/* Persists between images on purpose (mirrors reference behaviour). */
static int lasty = 0;

static void image_init(Image *im, int w, int h, int jw, int jh, int comps)
{
	int x;
	float resize_x;

	im->width = w;
	im->height = h;
	im->components = comps;
	im->pixel = calloc((size_t) w * h, sizeof(float));
	im->red = calloc((size_t) w * h, sizeof(float));
	im->green = calloc((size_t) w * h, sizeof(float));
	im->blue = calloc((size_t) w * h, sizeof(float));
	im->yadds = calloc((size_t) h, sizeof(int));
	im->lookup_x = calloc((size_t) w + 1, sizeof(int));
	if (!im->pixel || !im->red || !im->green || !im->blue || !im->yadds || !im->lookup_x) {
		fprintf(stderr, "Not enough memory for given output dimension\n");
		exit(1);
	}

	im->resize_y = (float) (h - 1) / (float) (jh - 1);
	resize_x = (float) (jw - 1) / (float) w;
	for (x = 0; x <= w; ++x)
		im->lookup_x[x] = ROUND((float) x * resize_x);
}

static void image_free(Image *im)
{
	free(im->pixel); free(im->red); free(im->green); free(im->blue);
	free(im->yadds); free(im->lookup_x);
}

static void process_scanline(Image *im, const JSAMPLE *scanline, int src_y)
{
	int y = ROUND(im->resize_y * (float) src_y);

	while (lasty <= y) {
		int row = lasty * im->width;
		int x;

		for (x = 0; x < im->width; ++x) {
			int xl = im->lookup_x[x];
			int xr = im->lookup_x[x + 1];
			int n = xr - xl + 1;
			float v = 0.0f, r = 0.0f, g = 0.0f, b = 0.0f;
			int s;

			if (im->components == 1) {
				for (s = xl; s <= xr; ++s) {
					float p = scanline[s];
					v += p / 255.0f;
				}
			} else {
				for (s = xl; s <= xr; ++s) {
					float pr = scanline[s * im->components];
					float pg = scanline[s * im->components + 1];
					float pb = scanline[s * im->components + 2];
					v += red_weight * pr / 255.0f + green_weight * pg / 255.0f + blue_weight * pb / 255.0f;
					r += pr / 255.0f;
					g += pg / 255.0f;
					b += pb / 255.0f;
				}
			}
			im->pixel[row + x] += v / n;
			im->red[row + x] += r / n;
			im->green[row + x] += g / n;
			im->blue[row + x] += b / n;
		}
		im->yadds[lasty]++;
		lasty++;
	}
	lasty = y;
}

static void image_normalize(Image *im)
{
	int x, y;
	for (y = 0; y < im->height; ++y) {
		int row = y * im->width;
		int n = im->yadds[y];
		if (!n) continue;
		for (x = 0; x < im->width; ++x) {
			im->pixel[row + x] /= n;
			im->red[row + x] /= n;
			im->green[row + x] /= n;
			im->blue[row + x] /= n;
		}
	}
}

/* ---------------------------------------------------------------------- */
/* Output                                                                  */
/* ---------------------------------------------------------------------- */

static int palette_index(float v)
{
	int n = (int) strlen(ascii_palette) - 1;
	int idx = ROUND(v * (float) n);
	if (invert)
		idx = n - idx;
	return idx;
}

/*
 * Pick an ANSI colour code (30..37) for a cell, 1 for bold, or 0 for
 * no colour at all.
 */
static int ansi_color(float r, float g, float b, float Y)
{
	const float t = 0.1f;

	if (grayscale)
		return Y > 0.7f ? 37 : 0;

	if (r - g > t && r - b > t) return 31;
	if (g - r > t && g - b > t) return 32;
	if (b - r > t && b - g > t) return 34;
	if (r - b > t && g - b > t && (r + g) / 2.0f > 0.45f) return 33;
	if (r - g > t && b - g > t && (r + b) / 2.0f > 0.45f) return 35;
	if (g - r > t && b - r > t && (g + b) / 2.0f > 0.45f) return 36;
	if (Y > 0.95f && r == 0.0f && g == 0.0f && b == 0.0f) return 1;
	if ((b - Y) + 0.6094f * (r - Y) >= 0.0f) return 37;
	return 0;
}

static void print_border_line(int w)
{
	int x;
	fputc('+', out);
	for (x = 0; x < w; ++x) fputc('-', out);
	fputs("+\n", out);
}

static void print_html_header(void)
{
	fputs("<?xml version='1.0' encoding='ISO-8859-1'?>\n", out);
	fputs("<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n", out);
	fputs("<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n", out);
	fputs("<head>\n", out);
	fprintf(out, "<title>%s</title>\n", html_title);
	fputs("<style type='text/css'>\n", out);
	fputs("body {\n", out);
	if (invert)
		fputs("   background-color: white;\n", out);
	else
		fputs("background-color: black;\n", out);
	fputs("}\n", out);
	fputs(".ascii {\n", out);
	fputs("   font-family: Courier;\n", out);
	if (!usecolors)
		fprintf(out, "   color: %s;\n", invert ? "black" : "white");
	fprintf(out, "   font-size:%dpt;\n", html_fontsize);
	fprintf(out, "   font-weight: %s;\n", html_bold ? "bold" : "normal");
	fputs("}\n", out);
	fputs("</style>\n", out);
	fputs("</head>\n", out);
	fputs("<body>\n", out);
	fputs("<div class='ascii'><pre>\n", out);
}

static void print_html_footer(void)
{
	fputs("</pre>\n", out);
	fputs("</div>\n", out);
	fputs("</body>\n", out);
	fputs("</html>\n", out);
}

static void print_html_char(char ch)
{
	switch (ch) {
	case ' ': fputs("&nbsp;", out); break;
	case '<': fputs("&lt;", out); break;
	case '>': fputs("&gt;", out); break;
	case '&': fputs("&amp;", out); break;
	default: fputc(ch, out); break;
	}
}

static void print_image(Image *im)
{
	int x, y;
	int w = im->width, h = im->height;
	int gray_source = im->components == 1;

	if (html && !html_raw)
		print_html_header();

	if (border)
		print_border_line(w);

	for (y = 0; y < h; ++y) {
		int yy = flipy ? h - 1 - y : y;
		int row = yy * w;

		if (border) fputc('|', out);

		for (x = 0; x < w; ++x) {
			int xx = flipx ? w - 1 - x : x;
			float Y = im->pixel[row + xx];
			float r = im->red[row + xx];
			float g = im->green[row + xx];
			float b = im->blue[row + xx];
			char ch = ascii_palette[palette_index(Y)];

			if (html && usecolors) {
				int R, G, B, R2, G2, B2;
				if (grayscale || gray_source) {
					int c = ROUND(255.0f * Y);
					if (gray_source && !grayscale && 255.0f * Y <= 1.0f)
						c = 0;
					R = G = B = c;
					R2 = G2 = B2 = ROUND(255.0f * Y * 0.5f);
				} else {
					R = ROUND(255.0f * r);
					G = ROUND(255.0f * g);
					B = ROUND(255.0f * b);
					R2 = ROUND(255.0f * r * Y);
					G2 = ROUND(255.0f * g * Y);
					B2 = ROUND(255.0f * b * Y);
				}
				if (colorfill)
					fprintf(out, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>",
						R2, G2, B2, R, G, B);
				else
					fprintf(out, "<span style='color:#%02x%02x%02x;'>", R, G, B);
				print_html_char(ch);
				fputs("</span>", out);
			} else if (usecolors) {
				int code = ansi_color(r, g, b, Y);
				if (code) {
					if (colorfill && code >= 30) code += 10;
					fprintf(out, "\033[%dm%c\033[0m", code, ch);
				} else {
					fputc(ch, out);
				}
			} else {
				fputc(ch, out);
			}
		}

		if (border) fputc('|', out);
		if (html && usecolors)
			fputs("<br/>", out);
		else
			fputc('\n', out);
	}

	if (border)
		print_border_line(w);

	if (html && !html_raw)
		print_html_footer();
}

/* ---------------------------------------------------------------------- */
/* Decoding                                                                */
/* ---------------------------------------------------------------------- */

static void print_progress(int done, int total)
{
	int n = ROUND(54.0f * (float) (done + 1) / (float) total);
	int i;
	fputs("Decompressing image [", stderr);
	for (i = 0; i < n; ++i) fputc('#', stderr);
	for (; i < 54; ++i) fputc('.', stderr);
	fputs("]\r", stderr);
}

static void decompress(FILE *fp, const char *label)
{
	struct jpeg_decompress_struct cinfo;
	struct jpeg_error_mgr jerr;
	Image im;
	JSAMPROW row;
	int jw, jh, comps, w, h;

	cinfo.err = jpeg_std_error(&jerr);
	jpeg_create_decompress(&cinfo);
	jpeg_stdio_src(&cinfo, fp);
	jpeg_read_header(&cinfo, 1);
	jpeg_start_decompress(&cinfo);

	jw = (int) cinfo.output_width;
	jh = (int) cinfo.output_height;
	comps = cinfo.output_components;

	compute_output_size(jw, jh, &w, &h);

	if (verbose) {
		if (label) fprintf(stderr, "%s\n", label);
		fprintf(stderr, "Source width: %d\n", jw);
		fprintf(stderr, "Source height: %d\n", jh);
		fprintf(stderr, "Source color components: %d\n", comps);
		fprintf(stderr, "Output width: %d\n", w);
		fprintf(stderr, "Output height: %d\n", h);
		fprintf(stderr, "Output palette (%d chars): '%s'\n", (int) strlen(ascii_palette), ascii_palette);
	}

	image_init(&im, w, h, jw, jh, comps);

	row = malloc((size_t) jw * comps);
	if (!row) {
		fprintf(stderr, "Not enough memory for scanline\n");
		exit(1);
	}

	while (cinfo.output_scanline < cinfo.output_height) {
		jpeg_read_scanlines(&cinfo, &row, 1);
		process_scanline(&im, row, (int) cinfo.output_scanline - 1);
		if (verbose)
			print_progress((int) cinfo.output_scanline, jh);
	}
	if (verbose)
		fputc('\n', stderr);

	image_normalize(&im);

	if (clearscr)
		fputs("\033[2J\033[0;0H", out);

	print_image(&im);

	image_free(&im);
	free(row);

	jpeg_finish_decompress(&cinfo);
	jpeg_destroy_decompress(&cinfo);
}

/* ---------------------------------------------------------------------- */
/* URL handling                                                            */
/* ---------------------------------------------------------------------- */

static int is_url(const char *s)
{
	return starts_with(s, "ftp://") || starts_with(s, "ftps://") ||
		starts_with(s, "file://") || starts_with(s, "http://") ||
		starts_with(s, "https://") || starts_with(s, "tftp://");
}

static void process_url(const char *url)
{
	int fd[2];
	pid_t pid;
	char label[4096];

	if (pipe(fd) != 0) {
		fprintf(stderr, "Could not create pipe\n");
		exit(1);
	}

	pid = fork();
	if (pid < 0) {
		fprintf(stderr, "Could not fork\n");
		exit(1);
	}

	if (pid == 0) {
		/* child: download */
		FILE *w;
		CURL *curl;
		close(fd[0]);
		w = fdopen(fd[1], "wb");
		if (!w) _exit(1);
		curl_global_init(CURL_GLOBAL_ALL);
		curl = curl_easy_init();
		if (curl) {
			curl_easy_setopt(curl, CURLOPT_URL, url);
			curl_easy_setopt(curl, CURLOPT_WRITEDATA, w);
			curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);
			curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
			curl_easy_setopt(curl, CURLOPT_VERBOSE, (long) debug);
			curl_easy_perform(curl);
			curl_easy_cleanup(curl);
		}
		fflush(w);
		fclose(w);
		curl_global_cleanup();
		_exit(0);
	}

	close(fd[1]);
	{
		FILE *r = fdopen(fd[0], "rb");
		if (!r) {
			fprintf(stderr, "Could not read from pipe\n");
			exit(1);
		}
		snprintf(label, sizeof label, "URL: %s", url);
		decompress(r, verbose ? label : NULL);
		fclose(r);
	}
	waitpid(pid, NULL, 0);
}

/* ---------------------------------------------------------------------- */

int main(int argc, char **argv)
{
	int i, nfiles = 0;

	for (i = 1; i < argc; ++i) {
		if (is_option(argv[i]))
			parse_option(argv[i]);
		else
			nfiles++;
	}

	if (nfiles == 0) {
		fprintf(stderr, "No files specified.\n\n");
		print_help();
		return 1;
	}

	apply_terminal_mode();
	validate_dimensions();

	if (red_weight + green_weight + blue_weight != 1.0f) {
		fprintf(stderr, "Weights RED + GREEN + BLUE must equal 1.0\n");
		return 1;
	}

	out = stdout;
	if (output_filename && strcmp(output_filename, "-") != 0) {
		out = fopen(output_filename, "wb");
		if (!out) {
			fprintf(stderr, "Could not open '%s' for writing.\n", output_filename);
			return 1;
		}
	}

	for (i = 1; i < argc; ++i) {
		const char *s = argv[i];
		if (is_option(s))
			continue;

		if (!strcmp(s, "-")) {
			decompress(stdin, NULL);
		} else if (is_url(s)) {
			process_url(s);
		} else {
			FILE *fp = fopen(s, "rb");
			char label[4096];
			if (!fp) {
				fprintf(stderr, "Can't open %s\n", s);
				return 1;
			}
			snprintf(label, sizeof label, "File: %s", s);
			decompress(fp, verbose ? label : NULL);
			fclose(fp);
		}
	}

	if (out != stdout)
		fclose(out);

	return 0;
}
