CC="${CC:-gcc}"
CFLAGS="-O2 -D_FORTIFY_SOURCE=2 -ffp-contract=off -fno-fast-math -Wall -Isrc"

# libjpeg: we ship our own API declarations (src/jpegapi.h) and link against
# the system libjpeg.so.8 directly, so no -dev package is needed.
JPEGLIB=""
for cand in /usr/lib/x86_64-linux-gnu/libjpeg.so.8 /usr/lib64/libjpeg.so.8 /usr/lib/libjpeg.so.8 /usr/lib/x86_64-linux-gnu/libjpeg.so /usr/lib64/libjpeg.so; do
	if [ -e "$cand" ]; then JPEGLIB="$cand"; break; fi
done
if [ -z "$JPEGLIB" ]; then
