#!/bin/sh
# Build the jp2a reimplementation into ./executable
set -e
cd "$(dirname "$0")"

CC="${CC:-gcc}"
CFLAGS="-O2 -U_FORTIFY_SOURCE -D_FORTIFY_SOURCE=2 -ffp-contract=off -fno-fast-math -Wall -Isrc"

# Try to make sure the (header) dependencies are present.  The build only
# needs the libcurl and ncurses development headers; libjpeg is used through
# our own API declarations (src/jpegapi.h) against the system libjpeg.so.8.
need_pkgs=""
[ -e /usr/include/x86_64-linux-gnu/curl/curl.h ] || [ -e /usr/include/curl/curl.h ] || need_pkgs="$need_pkgs libcurl4-openssl-dev"
[ -e /usr/include/term.h ] || need_pkgs="$need_pkgs libncurses-dev"
command -v "$CC" >/dev/null 2>&1 || need_pkgs="$need_pkgs gcc"
if [ -n "$need_pkgs" ]; then
	if command -v apt-get >/dev/null 2>&1; then
		(apt-get install -y $need_pkgs || sudo apt-get install -y $need_pkgs) 2>/dev/null || true
	fi
fi

JPEGLIB=""
for cand in /usr/lib/x86_64-linux-gnu/libjpeg.so.8 /usr/lib64/libjpeg.so.8 /usr/lib/libjpeg.so.8 \
            /usr/lib/x86_64-linux-gnu/libjpeg.so /usr/lib64/libjpeg.so /usr/lib/libjpeg.so; do
	if [ -e "$cand" ]; then JPEGLIB="$cand"; break; fi
done
[ -n "$JPEGLIB" ] || JPEGLIB="-ljpeg"

TINFO="-ltinfo"
if [ ! -e /usr/lib/x86_64-linux-gnu/libtinfo.so ] && [ ! -e /usr/lib64/libtinfo.so ] && [ ! -e /usr/lib/libtinfo.so ]; then
	TINFO="-lncurses"
fi

$CC $CFLAGS -o executable src/jp2a.c src/termsize.c "$JPEGLIB" -lcurl $TINFO -lm
EOF
